56	struct _mc_affix_set_t {
57	    // base_string is not owned
58	    const mc_utf8_string_with_bad_char_t *base_string;
59	    uint32_t *start_indices;
60	    uint32_t *end_indices;
61	    // Store counts per substring. As we expect heavy duplication of the padding value, this will save some time when we
62	    // hash later.
63	    uint32_t *substring_counts;
64	    uint32_t n_indices;
65	    uint32_t cur_idx;
66	};
67	
68	mc_affix_set_t *mc_affix_set_new(const mc_utf8_string_with_bad_char_t *base_string, uint32_t n_indices) {
69	    BSON_ASSERT_PARAM(base_string);
70	    mc_affix_set_t *set = (mc_affix_set_t *)bson_malloc0(sizeof(mc_affix_set_t));
71	    set->base_string = base_string;
72	    set->start_indices = (uint32_t *)bson_malloc0(sizeof(uint32_t) * n_indices);
73	    set->end_indices = (uint32_t *)bson_malloc0(sizeof(uint32_t) * n_indices);
74	    set->substring_counts = (uint32_t *)bson_malloc0(sizeof(uint32_t) * n_indices);
75	    set->n_indices = n_indices;
76	    return set;
77	}
78	
79	void mc_affix_set_destroy(mc_affix_set_t *set) {
80	    if (!set) {
81	        return;
82	    }
83	    bson_free(set->start_indices);
84	    bson_free(set->end_indices);
85	    bson_free(set->substring_counts);
86	    bson_free(set);
87	}
88	
89	bool mc_affix_set_insert(mc_affix_set_t *set, uint32_t base_start_idx, uint32_t base_end_idx) {
90	    BSON_ASSERT_PARAM(set);
91	    if (base_start_idx > base_end_idx || base_end_idx >= set->base_string->codepoint_len
92	        || set->cur_idx >= set->n_indices) {
93	        return false;
94	    }
95	    uint32_t idx = set->cur_idx++;
96	    set->start_indices[idx] = base_start_idx;
97	    set->end_indices[idx] = base_end_idx;
98	    set->substring_counts[idx] = 1;
99	    return true;
100	}
101	
102	bool mc_affix_set_insert_base_string(mc_affix_set_t *set, uint32_t count) {
103	    BSON_ASSERT_PARAM(set);
104	    if (count == 0 || set->cur_idx >= set->n_indices) {
105	        return false;
106	    }
107	    uint32_t idx = set->cur_idx++;
108	    set->start_indices[idx] = 0;
109	    set->end_indices[idx] = set->base_string->codepoint_len;
110	    set->substring_counts[idx] = count;
111	    return true;
112	}
113	
114	void mc_affix_set_iter_init(mc_affix_set_iter_t *it, mc_affix_set_t *set) {
115	    BSON_ASSERT_PARAM(it);
116	    BSON_ASSERT_PARAM(set);
117	    it->set = set;
118	    it->cur_idx = 0;
119	}
120	
121	bool mc_affix_set_iter_next(mc_affix_set_iter_t *it, const char **str, uint32_t *byte_len, uint32_t *count) {
122	    BSON_ASSERT_PARAM(it);
123	    if (it->cur_idx >= it->set->n_indices) {
124	        return false;
125	    }
126	    uint32_t idx = it->cur_idx++;
127	    uint32_t start_idx = it->set->start_indices[idx];
128	    uint32_t end_idx = it->set->end_indices[idx];
129	    uint32_t start_byte_offset = it->set->base_string->codepoint_offsets[start_idx];
130	    // Pointing to the end of the codepoints represents the end of the string.
131	    uint32_t end_byte_offset = it->set->base_string->buf.len;
132	    if (end_idx != it->set->base_string->codepoint_len) {
133	        end_byte_offset = it->set->base_string->codepoint_offsets[end_idx];
134	    }
135	    if (str) {
136	        *str = (const char *)it->set->base_string->buf.data + start_byte_offset;
137	    }
138	    if (byte_len) {
139	        *byte_len = end_byte_offset - start_byte_offset;
140	    }
141	    if (count) {
142	        *count = it->set->substring_counts[idx];
143	    }
144	    return true;
145	}
