147	// Linked list node in the hashset.
148	typedef struct _mc_substring_set_node_t {
149	    uint32_t start_offset;
150	    uint32_t byte_len;
151	    struct _mc_substring_set_node_t *next;
152	} mc_substring_set_node_t;
153	
154	static mc_substring_set_node_t *new_ssnode(uint32_t start_byte_offset, uint32_t byte_len) {
155	    mc_substring_set_node_t *ret = (mc_substring_set_node_t *)bson_malloc0(sizeof(mc_substring_set_node_t));
156	    ret->start_offset = start_byte_offset;
157	    ret->byte_len = byte_len;
158	    return ret;
159	}
