168	// FNV-1a hash function
169	static const uint32_t FNV1APRIME = 16777619;
170	static const uint32_t FNV1ABASIS = 2166136261;
171	
172	static uint32_t fnv1a(const uint8_t *data, uint32_t len) {
173	    BSON_ASSERT_PARAM(data);
174	    uint32_t hash = FNV1ABASIS;
175	    const uint8_t *ptr = data;
176	    while (ptr != data + len) {
177	        hash = (hash ^ (uint32_t)(*ptr++)) * FNV1APRIME;
178	    }
179	    return hash;
180	}
181	
182	// A reasonable default, balancing space with speed
183	#define HASHSET_SIZE 4096
184	
185	struct _mc_substring_set_t {
186	    // base_string is not owned
187	    const mc_utf8_string_with_bad_char_t *base_string;
188	    mc_substring_set_node_t *set[HASHSET_SIZE];
189	    uint32_t base_string_count;
190	};
