192	mc_substring_set_t *mc_substring_set_new(const mc_utf8_string_with_bad_char_t *base_string) {
193	    BSON_ASSERT_PARAM(base_string);
194	    mc_substring_set_t *set = (mc_substring_set_t *)bson_malloc0(sizeof(mc_substring_set_t));
195	    set->base_string = base_string;
196	    return set;
197	}
