199	void mc_substring_set_destroy(mc_substring_set_t *set) {
200	    if (!set) {
201	        return;
202	    }
203	    for (int i = 0; i < HASHSET_SIZE; i++) {
204	        mc_substring_set_node_t *node = set->set[i];
205	        while (node) {
206	            mc_substring_set_node_t *to_destroy = node;
207	            node = node->next;
208	            mc_substring_set_node_destroy(to_destroy);
209	        }
210	    }
211	    bson_free(set);
212	}
