28	                                                      uint32_t unfolded_codepoint_len,
29	                                                      uint32_t lb,
30	                                                      uint32_t ub,
31	                                                      bool is_prefix) {
32	    BSON_ASSERT_PARAM(base_str);
33	    // 16 * ceil(unfolded codepoint len / 16)
34	    uint32_t cbclen = 16 * (uint32_t)((unfolded_codepoint_len + 15) / 16);
35	    if (cbclen < lb) {
36	        // No valid substrings, return empty tree
37	        return NULL;
38	    }
39	
40	    // Total number of substrings
41	    uint32_t msize = BSON_MIN(cbclen, ub) - lb + 1;
42	    uint32_t folded_codepoint_len = base_str->codepoint_len - 1; // remove one codepoint for 0xFF
43	    uint32_t real_max_len = BSON_MIN(folded_codepoint_len, ub);
44	    // Number of actual substrings, excluding padding
45	    uint32_t real_substrings = real_max_len >= lb ? real_max_len - lb + 1 : 0;
46	    // If real_substrings and msize differ, we need to insert padding, so allocate one extra slot.
47	    uint32_t set_size = real_substrings == msize ? real_substrings : real_substrings + 1;
48	    mc_affix_set_t *set = mc_affix_set_new(base_str, set_size);
49	    uint32_t n_inserted = 0;
50	    for (uint32_t i = lb; i < real_max_len + 1; i++, n_inserted++) {
51	        if (is_prefix) {
52	            // [0, lb), [0, lb + 1), ..., [0, min(len, ub))
53	            BSON_ASSERT(mc_affix_set_insert(set, 0, i));
54	        } else {
55	            // [len - lb, len), [len - lb - 1, len), ..., [max(0, len - ub), len)
56	            BSON_ASSERT(mc_affix_set_insert(set, folded_codepoint_len - i, folded_codepoint_len));
57	        }
58	    }
59	    if (msize != real_substrings) {
60	        // Insert padding to get to msize
61	        BSON_ASSERT(mc_affix_set_insert_base_string(set, msize - real_substrings));
